		problem: "// 不安全寫法：進入 deep-sleep 前沒清除含機密的緩衝區 => 低電源域可讀到殘留\nstatic uint8_t keybuf[32];\n\nvoid enter_deep_sleep(void) {\n    // keybuf 裡的機密仍留在 RAM,debug/low-power 域接著可讀走\n    enter_sleep_mode();\n}",
